import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class StarterDeck100DiscardBenchTest {
    static final UUID A=StarterDeck100PokemonTest.A,B=StarterDeck100PokemonTest.B;
    static String id(int n){return StarterDeck100PokemonTest.id(n);}
    static void check(boolean ok,String why){StarterDeck100PokemonTest.check(ok,why);}
    static CardInstance handB(ServerMatch m,String id){var found=m.privateView(B).hand().stream().filter(c->c.definitionId().equals(id)).findFirst();if(found.isPresent())return found.get();var c=m.privateView(B).deck().stream().filter(x->x.definitionId().equals(id)).findFirst().orElseThrow();m.searchOwnDeckToHandByEffect(B,List.of(c.instanceId()));return c;}
    public static void main(String[] args){horn(false);horn(true);malformed();System.out.println("StarterDeck100DiscardBenchTest passed: opposing public discard, controller choice, Basic-only, destination owner/capacity, atomic rejection, replay rejection and no shuffle");}
    static void horn(boolean full){var m=StarterDeck100PokemonTest.game(1,150,id(380));var horn=StarterDeck100PokemonTest.hand(m,id(380));TopDeckLookTest.rejects(()->m.playTrainer(A,horn.instanceId(),null));var own=StarterDeck100PokemonTest.hand(m,id(1));m.discardHandCardsByEffect(A,A,List.of(own.instanceId()));m.endTurn(A);var basic=handB(m,id(149));var evo=handB(m,id(150));m.discardHandCardsByEffect(B,B,List.of(basic.instanceId(),evo.instanceId()));if(full)while(m.benchPokemonView(B).size()<5)m.playBasicPokemonToBench(B,handB(m,id(149)).instanceId());m.endTurn(B);
        if(full){TopDeckLookTest.rejects(()->m.playTrainer(A,horn.instanceId(),null));check(m.privateView(A).hand().contains(horn)&&m.privateView(B).discard().contains(basic),"full bench consumed cards");return;}
        int rng=m.randomTranscript().size(),ownBench=m.benchPokemonView(A).size(),oppBench=m.benchPokemonView(B).size();m.playTrainer(A,horn.instanceId(),null);var p=m.effectCardPrompt(A);check(p.candidates().equals(List.of(basic)),"offered own discard or evolution");TopDeckLookTest.rejects(()->m.effectCardPrompt(B));for(var wrong:List.of(own,evo,horn))TopDeckLookTest.rejects(()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(wrong.instanceId())));TopDeckLookTest.rejects(()->m.submitEffectCards(B,p.resolutionId(),p.step(),List.of(basic.instanceId())));TopDeckLookTest.rejects(()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of()));check(m.privateView(B).discard().contains(basic),"invalid selection mutated discard");m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(basic.instanceId()));var revived=StarterDeck100PokemonTest.view(m,B,basic.instanceId());check(m.benchPokemonView(B).size()==oppBench+1&&m.benchPokemonView(A).size()==ownBench&&!m.privateView(B).discard().contains(basic)&&m.privateView(B).discard().contains(evo),"wrong destination/card removed");check(revived.damage()==0&&revived.conditions().isEmpty()&&revived.attachedEnergyIds().isEmpty(),"revived Pokemon retained state");check(m.randomTranscript().size()==rng,"public discard revival shuffled");TopDeckLookTest.rejects(()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(basic.instanceId())));
    }
    static void malformed(){String good="{\"type\":\"search_discard_pile\",\"target\":\"DISCARD\",\"amount\":1,\"minimum\":1,\"card_category\":\"POKEMON\",\"basic_pokemon_only\":true,\"source_owner\":\"OPPONENT\",\"destination\":\"BENCH\"}";for(String bad:List.of(good.replace("BENCH","HAND"),good.replace("OPPONENT","SELF"),good.replace("basic_pokemon_only\":true","basic_pokemon_only\":false"))){TopDeckLookTest.rejects(()->ZoneSelectionEffect.forProgram(EffectRegistry.standard().parse(com.google.gson.JsonParser.parseString(bad).getAsJsonObject())));}}
}
